        if (darkModeCb) {
            darkModeCb.addEventListener('change', () => {
                applyDarkMode(darkModeCb.checked);
            });
        }

        document.getElementById('close-btn').addEventListener('click', () => {
            try { window.close(); } catch (_) {}
        });

        window.addEventListener('focus', syncUI);
